const input = $json;


// ============================================================
// 1. Проверка входа
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет field_key'
  );
}

if (!Array.isArray(input.candidates)) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] candidates должен быть массивом'
  );
}


// ============================================================
// 2. Определяем раунд агрегации
//
// Round 1:
//   обычные facts после анализа документов.
//
// Round 2:
//   старые facts + кандидаты Targeted Recheck.
// ============================================================

const aggregationRound =
  Number(input.aggregation_round ?? 1);

if (
  aggregationRound !== 1 &&
  aggregationRound !== 2
) {
  throw new Error(
    `[Подготовить запрос Semantic Aggregator] Недопустимый aggregation_round=${aggregationRound}`
  );
}


// В первом раунде идентификатор кандидата — fact_id.
// Во втором — candidate_ref.
const candidateIdKey =
  aggregationRound === 1
    ? 'fact_id'
    : 'candidate_ref';


// ============================================================
// 3. Правила смысловой агрегации по field_key
// ============================================================

