  );

  effectiveFieldRules.push(
  'Если candidate origin="targeted_recheck" имеет validator_verdict="requires_review", он не считается подтверждённым улучшением существующего candidate и сам по себе не может привести поле к status="resolved".'
);
}


// ============================================================
// 5. Компактная нормализация evidence
// ============================================================

function normalizeEvidence(item) {

  if (
    !item ||
    typeof item !== 'object'
  ) {
    return null;
  }


  // ----------------------------------------------------------
  // Evidence из Targeted Recheck:
  // semantic block
  // ----------------------------------------------------------

  if (
    item.source_type ===
    'semantic_block'
  ) {

    return {
      source_type:
        'semantic_block',

      analysis_unit_id:
        item.analysis_unit_id ?? null,

      semantic_block_id:
        item.semantic_block_id ?? null,

      quote:
        item.quote ?? null,
    };
  }


  // ----------------------------------------------------------
  // Evidence из Targeted Recheck:
  // tender metadata
  // ----------------------------------------------------------

  if (
    item.source_type ===
    'tender_metadata'
  ) {

    return {
      source_type:
        'tender_metadata',

      metadata_key:
        item.metadata_key ?? null,

      value:
        item.value ?? null,
    };
  }


  // ----------------------------------------------------------
  // Обычный evidence первого прохода
  // ----------------------------------------------------------

  return {
    quote:
      item.quote ?? null,

    type:
      item.type ?? null,

    role:
      item.role ?? null,

    page_from:
      item.page_from ?? null,

    page_to:
      item.page_to ?? null,

    sheet_name:
      item.sheet_name ?? null,

    semantic_block_id:
      item.semantic_block_id ?? null,
  };
}


// ============================================================
// 6. Нормализуем candidates
// ============================================================

const candidatesForAi =
  input.candidates.map(
    (candidate, index) => {

      let candidateId;


      // --------------------------------------------------------
      // Round 1
      // --------------------------------------------------------

      if (aggregationRound === 1) {

        candidateId =
          candidate.fact_id;

        if (!candidateId) {
          throw new Error(
            `[Подготовить запрос Semantic Aggregator] У кандидата ${index} отсутствует fact_id`
          );
        }
      }


      // --------------------------------------------------------
      // Round 2
      // --------------------------------------------------------

      if (aggregationRound === 2) {

        candidateId =
          candidate.candidate_ref;

        if (!candidateId) {
