const aiResponse = $json;

const source =
  $('Подготовить запрос #2 Semantic Aggregator').item.json;


// ============================================================
// 1. Определяем раунд агрегации
// ============================================================

const aggregationRound =
  Number(source.aggregation_round ?? 1);

if (
  aggregationRound !== 1 &&
  aggregationRound !== 2
) {
  throw new Error(
    `[Semantic Aggregator Validator] Недопустимый aggregation_round=${aggregationRound}`
  );
}


const candidateIdKey =
  aggregationRound === 1
    ? 'fact_id'
    : 'candidate_ref';


const supportingListKey =
  aggregationRound === 1
    ? 'supporting_fact_ids'
    : 'supporting_candidate_refs';


const conflictListKey =
  aggregationRound === 1
    ? 'conflict_fact_ids'
    : 'conflict_candidate_refs';


// ============================================================
// 2. Проверяем технический ответ API
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[Semantic Aggregator Validator] В ответе отсутствует choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный finish_reason: ${choice.finish_reason}`
  );
}


const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[Semantic Aggregator Validator] message.content пуст'
  );
}


// ============================================================
// 3. Парсим JSON модели
// ============================================================

let result;

try {

  result =
    JSON.parse(content);

} catch (error) {

  throw new Error(
    `[Semantic Aggregator Validator] Модель вернула невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 4. Разрешённые значения
// ============================================================

const ALLOWED_ROLES =
  new Set([
    'primary',
    'duplicate',
    'supporting',
    'complement',
    'conflict',
    'not_applicable',
  ]);


const ALLOWED_UNRESOLVED_CODES =
  new Set([
    'conflicting_candidates',
    'insufficient_evidence',
    'ambiguous_scope',
    'no_reliable_candidate',
    'other',
  ]);


const allowedStatuses =
  aggregationRound === 1

    ? new Set([
        'resolved',
        'requires_recheck',
      ])

    : new Set([
        'resolved',
        'requires_review',
      ]);


// ============================================================
// 5. Проверяем field_key
// ============================================================

if (
  result.field_key !==
  source.field_key
) {
  throw new Error(
    `[Semantic Aggregator Validator] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}


// ============================================================
// 6. Проверяем status
// ============================================================

if (
  !allowedStatuses.has(
    result.status
  )
) {
  throw new Error(
    `[Semantic Aggregator Validator] Недопустимый status=${result.status} для Round ${aggregationRound}`
  );
}


// ============================================================
// 7. Проверяем confidence
// ============================================================

if (
  typeof result.confidence !== 'number' ||
  !Number.isFinite(result.confidence) ||
  result.confidence < 0 ||
  result.confidence > 1
) {
  throw new Error(
    `[Semantic Aggregator Validator] Некорректный confidence=${result.confidence}`
  );
}


// ============================================================
// 8. Получаем allow-list кандидатов
// ============================================================

let allowedCandidateIds;


if (
  Array.isArray(
    source.allowed_candidate_ids
  )
) {

  allowedCandidateIds =
    source.allowed_candidate_ids;

} else if (
  aggregationRound === 1 &&
  Array.isArray(source.allowed_fact_ids)
) {

  allowedCandidateIds =
    source.allowed_fact_ids;

} else if (
  aggregationRound === 2 &&
  Array.isArray(source.allowed_candidate_refs)
) {

  allowedCandidateIds =
    source.allowed_candidate_refs;

} else {

  throw new Error(
    '[Semantic Aggregator Validator] Не найден allow-list кандидатов'
  );
}


const allowedCandidateIdSet =
  new Set(
    allowedCandidateIds
  );


if (
  allowedCandidateIdSet.size !==
  allowedCandidateIds.length
) {
  throw new Error(
    `[Semantic Aggregator Validator] Во входном allow-list есть повторяющиеся ${candidateIdKey}`
  );
}


// ============================================================
// 9. Проверяем candidate_decisions
// ============================================================

if (
  !Array.isArray(
    result.candidate_decisions
  )
) {
  throw new Error(
    '[Semantic Aggregator Validator] candidate_decisions должен быть массивом'
  );
}


if (
  result.candidate_decisions.length !==
  allowedCandidateIds.length
) {
  throw new Error(
    `[Semantic Aggregator Validator] Ожидалось ${allowedCandidateIds.length} candidate_decisions, получено ${result.candidate_decisions.length}`
  );
}


const usedCandidateIds =
  new Set();


const decisionByCandidateId =
  new Map();


for (
  let index = 0;
  index < result.candidate_decisions.length;
  index++
) {

  const decision =
    result.candidate_decisions[index];


  const candidateId =
    decision?.[candidateIdKey];


  // ----------------------------------------------------------
  // ID кандидата
  // ----------------------------------------------------------

  if (
    typeof candidateId !== 'string' ||
    !candidateId
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] candidate_decision[${index}] без ${candidateIdKey}`
    );
  }


  if (
    !allowedCandidateIdSet.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Модель придумала неизвестный ${candidateIdKey}=${candidateId}`
    );
  }


  if (
    usedCandidateIds.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] ${candidateIdKey} повторяется: ${candidateId}`
    );
  }


  usedCandidateIds.add(
    candidateId
  );


  // ----------------------------------------------------------
  // role
  // ----------------------------------------------------------

  if (
    !ALLOWED_ROLES.has(
      decision.role
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Недопустимая role=${decision.role} для ${candidateIdKey}=${candidateId}`
    );
  }


  // ----------------------------------------------------------
  // reason
  // ----------------------------------------------------------

  if (
    typeof decision.reason !== 'string' ||
    !decision.reason.trim()
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Нет reason для ${candidateIdKey}=${candidateId}`
    );
  }


  decisionByCandidateId.set(
    candidateId,
    decision
  );
}


// ============================================================
// 10. Убеждаемся, что ни один входной candidate не потерян
// ============================================================

for (
  const candidateId
  of allowedCandidateIds
) {

  if (
    !usedCandidateIds.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] В ответе потерян ${candidateIdKey}=${candidateId}`
    );
  }
}


// ============================================================
// 11. Проверяем supporting list
// ============================================================

const supportingList =
  result?.[supportingListKey];


if (
  !Array.isArray(
    supportingList
  )
) {
  throw new Error(
    `[Semantic Aggregator Validator] ${supportingListKey} должен быть массивом`
  );
}


const supportingSet =
  new Set();


for (
  const candidateId
  of supportingList
) {

  if (
    typeof candidateId !== 'string' ||
    !candidateId
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный ID в ${supportingListKey}`
    );
  }


  if (
    !allowedCandidateIdSet.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный supporting ${candidateIdKey}=${candidateId}`
    );
  }


  if (
    supportingSet.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат supporting ${candidateIdKey}=${candidateId}`
    );
  }


  supportingSet.add(
    candidateId
  );


  const role =
    decisionByCandidateId
      .get(candidateId)
      ?.role;


  if (
    role === 'conflict' ||
    role === 'not_applicable'
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] ${candidateIdKey}=${candidateId} имеет role=${role}, но указан как supporting`
    );
  }
}


// ============================================================
// 12. Проверяем conflict list
// ============================================================

const conflictList =
  result?.[conflictListKey];


if (
  !Array.isArray(
    conflictList
  )
) {
  throw new Error(
    `[Semantic Aggregator Validator] ${conflictListKey} должен быть массивом`
  );
}


const conflictSet =
  new Set();


for (
  const candidateId
  of conflictList
) {

  if (
    typeof candidateId !== 'string' ||
    !candidateId
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный ID в ${conflictListKey}`
    );
  }


  if (
    !allowedCandidateIdSet.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Неизвестный conflict ${candidateIdKey}=${candidateId}`
    );
  }


  if (
    conflictSet.has(
      candidateId
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Дубликат conflict ${candidateIdKey}=${candidateId}`
    );
  }


  conflictSet.add(
    candidateId
  );
}


// ============================================================
// 13. Все role=conflict обязаны совпадать с conflict list
// ============================================================

for (
  const decision
  of result.candidate_decisions
) {

  const candidateId =
    decision[candidateIdKey];


  const listedAsConflict =
    conflictSet.has(
      candidateId
    );


  if (
    decision.role === 'conflict' &&
    !listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] ${candidateIdKey}=${candidateId} имеет role=conflict, но отсутствует в ${conflictListKey}`
    );
  }


  if (
    decision.role !== 'conflict' &&
    listedAsConflict
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] ${candidateIdKey}=${candidateId} указан в ${conflictListKey}, но role=${decision.role}`
    );
  }
}


// ============================================================
// 14. Считаем primary
// ============================================================

const primaryCount =
  result.candidate_decisions
    .filter(
      decision =>
        decision.role ===
        'primary'
    )
    .length;


// ============================================================
// 15. Общая проверка resolved
// ============================================================

if (
  result.status ===
  'resolved'
) {

  if (
    typeof result.final_value_text !== 'string' ||
    !result.final_value_text.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved требуется final_value_text'
    );
  }


  if (
    result.needs_recheck !== false
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для resolved needs_recheck должен быть false'
    );
  }


  if (
    primaryCount !== 1
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Для resolved ожидается ровно один primary, получено ${primaryCount}`
    );
  }


  if (
    conflictSet.size > 0
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] resolved не может содержать unresolved conflict'
    );
  }
}


// ============================================================
// 16. Round 1: resolved
// ============================================================

if (
  aggregationRound === 1 &&
  result.status === 'resolved'
) {

  if (
    result.recheck_reason_code !== null
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Round 1 resolved: recheck_reason_code должен быть null'
    );
  }


  if (
    result.recheck_note !== null
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Round 1 resolved: recheck_note должен быть null'
    );
  }
}


// ============================================================
// 17. Round 1: requires_recheck
// ============================================================

if (
  aggregationRound === 1 &&
  result.status === 'requires_recheck'
) {

  if (
    result.needs_recheck !== true
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck needs_recheck должен быть true'
    );
  }


  if (
    !ALLOWED_UNRESOLVED_CODES.has(
      result.recheck_reason_code
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный recheck_reason_code=${result.recheck_reason_code}`
    );
  }


  if (
    typeof result.recheck_note !== 'string' ||
    !result.recheck_note.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_recheck нужен recheck_note'
    );
  }


  if (
    primaryCount > 1
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Для requires_recheck не может быть больше одного primary, получено ${primaryCount}`
    );
  }
}


// ============================================================
// 18. Round 2: needs_recheck всегда false
// ============================================================

if (
  aggregationRound === 2
) {

  if (
    result.needs_recheck !== false
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Round 2: повторный Targeted Recheck запрещён, needs_recheck должен быть false'
    );
  }
}


// ============================================================
// 19. Round 2: resolved
// ============================================================

if (
  aggregationRound === 2 &&
  result.status === 'resolved'
) {

  if (
    result.review_reason_code !== null
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Round 2 resolved: review_reason_code должен быть null'
    );
  }


  if (
    result.review_note !== null
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Round 2 resolved: review_note должен быть null'
    );
  }
}


// ============================================================
// 20. Round 2: requires_review
// ============================================================

if (
  aggregationRound === 2 &&
  result.status === 'requires_review'
) {

  if (
    !ALLOWED_UNRESOLVED_CODES.has(
      result.review_reason_code
    )
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Некорректный review_reason_code=${result.review_reason_code}`
    );
  }


  if (
    typeof result.review_note !== 'string' ||
    !result.review_note.trim()
  ) {
    throw new Error(
      '[Semantic Aggregator Validator] Для requires_review нужен review_note'
    );
  }


  if (
    primaryCount > 1
  ) {
    throw new Error(
      `[Semantic Aggregator Validator] Для requires_review не может быть больше одного primary, получено ${primaryCount}`
    );
  }
}


// ============================================================
// 20.1. Field-specific terminal containment
// ============================================================

const reportedStatus =
  result.status;


const ROUND2_CONTAINMENT_BY_FIELD = {
  application_documents: {
    policy: 'application_documents_round2_requires_review_v1',
    reason: 'Полнота составного перечня документов заявки не доказана; требуется ручная проверка.',
  },
  participation_guarantee: {
    policy: 'participation_guarantee_round2_requires_review_v1',
    reason: 'Фактическая применимость обеспечения заявки и его размер не доказаны; требуется ручная проверка.',
  },
  required_official_certificates: {
    policy: 'required_official_certificates_round2_requires_review_v1',
    reason: 'Полнота перечня обязательных официальных документов об участнике и его статусе не доказана; требуется ручная проверка.',
  },
};

const containmentRule =
  aggregationRound === 2 &&
  source.field_catalog_version === 'tender_fields_v1' &&
  source.field_key === result.field_key &&
  reportedStatus === 'resolved'
    ? ROUND2_CONTAINMENT_BY_FIELD[source.field_key] ?? null
    : null;

const containmentApplied =
  containmentRule !== null;


const effectiveStatus =
  containmentApplied
    ? 'requires_review'
    : reportedStatus;


const effectiveReviewReasonCode =
  containmentApplied
    ? 'insufficient_evidence'
    : result.review_reason_code;


const effectiveReviewNote =
  containmentApplied
    ? containmentRule.reason
    : result.review_note;


const containmentPolicy =
  containmentApplied
    ? containmentRule.policy
    : null;


const containmentReason =
  containmentApplied
    ? containmentRule.reason
    : null;


// ============================================================
// 21. Нормализованный output
// ============================================================

const output = {

  analysis_run_id:
    source.analysis_run_id,

  field_catalog_version:
    source.field_catalog_version,

  field_index:
    source.field_index,

  field_key:
    source.field_key,

  aggregation_round:
    aggregationRound,

  candidate_id_key:
    candidateIdKey,

  aggregation_status:
    effectiveStatus,

  final_value_text:
    result.final_value_text ?? null,

  confidence:
    result.confidence,

  candidate_decisions:
    result.candidate_decisions,

  supporting_candidate_ids:
    supportingList,

  conflict_candidate_ids:
    conflictList,

  needs_recheck:
    result.needs_recheck,

  aggregation_input:
    source.aggregation_input,

  recheck_attempt:
  source.recheck_attempt ?? null,

  recheck_outcome:
  source.recheck_outcome ?? null,

recheck_note:
  source.recheck_note ?? null,

evidence_validated:
  source.evidence_validated === true,

validator_validated:
  source.validator_validated === true,

original_aggregation:
  source.original_aggregation ?? null,

recheck_profile:
  source.recheck_profile ?? null,

allowed_metadata:
  source.allowed_metadata ?? {},

targeted_recheck_meta:
  source.targeted_recheck_meta ?? null,

validator_meta:
  source.validator_meta ?? null,

post_validator_route:
  source.post_validator_route ?? null,

post_validator_route_reason:
  source.post_validator_route_reason ?? null,

rejected_candidates:
  Array.isArray(source.rejected_candidates)
    ? source.rejected_candidates
    : [],

  semantic_aggregator_meta: {

    reported_status:
      reportedStatus,

    effective_status:
      effectiveStatus,

    containment_applied:
      containmentApplied,

    containment_policy:
      containmentPolicy,

    containment_reason:
      containmentReason,

    response_id:
      aiResponse.id ?? null,

    model:
      aiResponse.model ?? null,

    finish_reason:
      choice.finish_reason,

    usage:
      aiResponse.usage ?? null,
  },

  aggregation_validated:
    true,
};


// ============================================================
// 22. Поля Round 1 для обратной совместимости
// ============================================================

if (
  aggregationRound === 1
) {

  output.supporting_fact_ids =
    supportingList;

  output.conflict_fact_ids =
    conflictList;

  output.recheck_reason_code =
    result.recheck_reason_code;

  output.recheck_note =
    result.recheck_note;
}


// ============================================================
// 23. Поля Round 2
// ============================================================

if (
  aggregationRound === 2
) {

  output.supporting_candidate_refs =
    supportingList;

  output.conflict_candidate_refs =
    conflictList;

  output.review_reason_code =
    effectiveReviewReasonCode;

  output.review_note =
    effectiveReviewNote;
}


return {
  json: output,
};

