const wrapper = $json;

const input =
  wrapper.original_input &&
  typeof wrapper.original_input === 'object'
    ? wrapper.original_input
    : null;

if (!input) {
  throw new Error(
    '[Targeted Recheck Request] Нет original_input после загрузки tender_meta'
  );
}

const tenderMeta =
  wrapper.tender_meta &&
  typeof wrapper.tender_meta === 'object'
    ? wrapper.tender_meta
    : {};


// ============================================================
// 1. Базовая проверка входа
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Targeted Recheck Request] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Targeted Recheck Request] Нет field_key'
  );
}


// ============================================================
// 2. Определяем, ПОЧЕМУ поле пришло в Targeted Recheck
//
// Поддерживаем два сценария:
//
// A. aggregation_recheck
//    Кандидаты уже были,
//    Semantic Aggregator попросил перепроверку.
//
// B. no_initial_candidates
//    Первичный анализ вообще не нашёл кандидатов,
//    Metadata Resolver тоже не смог закрыть поле.
// ============================================================

const originalField =
  input.original_field &&
  typeof input.original_field === 'object'
    ? input.original_field
    : null;


const isAggregationRecheck =
  input.needs_recheck === true;


const isNoInitialCandidates =
  input.metadata_resolved === false &&
  originalField?.has_candidates === false &&
  Array.isArray(originalField?.candidates) &&
  originalField.candidates.length === 0;


let recheckTrigger = null;

if (isAggregationRecheck) {

  recheckTrigger =
    'aggregation_recheck';

} else if (isNoInitialCandidates) {

  recheckTrigger =
    'no_initial_candidates';

} else {

  throw new Error(
    '[Targeted Recheck Request] Не удалось определить допустимый сценарий Targeted Recheck'
