    [...selectedIndexes]
      .sort((a, b) => a - b)
      .map(index => {

        const segment =
          segments[index];

        const match =
          segmentMatches.get(index);

        return {
          semantic_block_id:
            segment.semantic_block_id,

          type:
            segment.type ?? null,

          role:
            segment.role ?? null,

          scope:
            segment.scope ?? null,

