// Следующая deterministic-нода сможет проверить,
// что AI не сослался на придуманный block.
// ============================================================

const allowedSemanticBlocks =
  contextForAi.flatMap(unit =>
    unit.segments
      .filter(
        segment =>
          segment.semantic_block_id &&
          typeof segment.text === 'string'
      )
      .map(segment => ({
        analysis_unit_id:
          unit.analysis_unit_id,

        semantic_block_id:
          segment.semantic_block_id,

        text:
          segment.text,
      }))
  );


// ============================================================
// 10. Output
// ============================================================

return {
  json: {

    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    recheck_attempt:
      input.recheck_attempt,


    system_prompt:
      systemPrompt,

    user_prompt:
      userPrompt,


    allowed_semantic_blocks:
      allowedSemanticBlocks,

    allowed_metadata:
      tenderMetadata,


    original_aggregation:
      input.original_aggregation,

    existing_candidates:
      existingCandidates,

    recheck_profile:
      profile,

    recheck_context:
      contextForAi,
  },
};

