parameters.jsCode:
const input = $json;


// ============================================================
// 1. Проверяем вход
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Подготовить #2 Validator Targeted Recheck] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Подготовить #2 Validator Targeted Recheck] Нет field_key'
  );
}

if (input.evidence_validated !== true) {
  throw new Error(
    '[Подготовить #2 Validator Targeted Recheck] evidence не прошёл детерминированную проверку'
  );
}

if (input.recheck_outcome !== 'candidate_found') {
  throw new Error(
    `[Подготовить #2 Validator Targeted Recheck] Ожидался recheck_outcome=candidate_found, получено ${input.recheck_outcome}`
  );
}

if (!Array.isArray(input.candidates)) {
  throw new Error(
    '[Подготовить #2 Validator Targeted Recheck] candidates должен быть массивом'
  );
}

if (input.candidates.length === 0) {
  throw new Error(
    '[Подготовить #2 Validator Targeted Recheck] candidates пуст'
  );
}


// ============================================================
// 2. Профиль проверяемого поля
// ============================================================

const profile =
  input.recheck_profile &&
  typeof input.recheck_profile === 'object'
    ? input.recheck_profile
    : {};

const profileTitle =
  typeof profile.title === 'string' &&
  profile.title.trim()
    ? profile.title.trim()
    : input.field_key;

const profileObjective =
  typeof profile.objective === 'string' &&
  profile.objective.trim()
    ? profile.objective.trim()
    : 'Проверить логическую обоснованность найденного candidate для целевого поля.';

const profileRules =
  Array.isArray(profile.rules)
    ? profile.rules
        .map(rule => String(rule ?? '').trim())
        .filter(Boolean)
    : [];


// ============================================================
// 3. Проверяем candidate_index
// ============================================================

const candidateIndexes =
  input.candidates.map(
    candidate => candidate.candidate_index
  );

const candidateIndexSet =
  new Set();


for (
  let position = 0;
  position < input.candidates.length;
  position++
) {
  const candidate =
    input.candidates[position];

  if (
    !Number.isInteger(
      candidate.candidate_index
    )
  ) {
    throw new Error(
      `[Подготовить #2 Validator Targeted Recheck] candidate_index не integer у candidate position=${position}`
    );
  }

  if (
    candidateIndexSet.has(
      candidate.candidate_index
    )
  ) {
    throw new Error(
      `[Подготовить #2 Validator Targeted Recheck] Повтор candidate_index=${candidate.candidate_index}`
    );
  }

  candidateIndexSet.add(
    candidate.candidate_index
  );
}


// ============================================================
// 4. Определяем analysis units,
// на которые реально ссылаются candidates
//
// Validator не нужно повторно отправлять вообще весь retrieval.
// Оставляем целиком только те analysis units,
// внутри которых находится evidence кандидатов.
// Это сохраняет локальный контекст вокруг цитаты,
// но уменьшает шум и токены.
// ============================================================

const referencedUnitIds =
  new Set();

for (const candidate of input.candidates) {

  const evidenceItems =
    Array.isArray(candidate.evidence)
      ? candidate.evidence
      : [];

  for (const evidence of evidenceItems) {

    if (
      evidence?.source_type === 'semantic_block' &&
      evidence.analysis_unit_id
    ) {
      referencedUnitIds.add(
        evidence.analysis_unit_id
      );
    }
  }
}


const contextForValidator =
  (Array.isArray(input.recheck_context)
    ? input.recheck_context
    : []
  )
    .filter(
      unit =>
        referencedUnitIds.has(
          unit.analysis_unit_id
        )
    )
    .map(unit => ({
      analysis_unit_id:
        unit.analysis_unit_id,

      document:
        unit.document ?? null,

      section_title:
        unit.section_title ?? null,

      source_pages:
        unit.source_pages ?? [],

      segments:
        (Array.isArray(unit.segments)
          ? unit.segments
          : []
        ).map(segment => ({
          semantic_block_id:
            segment.semantic_block_id ?? null,

          type:
            segment.type ?? null,

          role:
            segment.role ?? null,

          text:
            segment.text ?? '',
        })),
    }));


// ============================================================
// 5. Structured metadata
// ============================================================

const tenderMetadata =
  input.allowed_metadata &&
  typeof input.allowed_metadata === 'object'
    ? input.allowed_metadata
    : {};


// ============================================================
// 6. System Prompt
// ============================================================

const systemPrompt = `
Ты — независимый AI Validator системы анализа тендерной документации.

Перед тобой находятся candidate facts,
полученные отдельным Targeted Recheck Extractor
для ОДНОГО конкретного поля тендера.

До тебя детерминированная система уже проверила:

- что analysis_unit_id существуют;
- что semantic_block_id существуют;
- что документные quote действительно находятся
  в соответствующих semantic blocks;
- что переданные metadata evidence используют
  разрешённые structured metadata.

Поэтому НЕ нужно повторно проверять техническое существование evidence.

Твоя задача —
проверить ЛОГИЧЕСКУЮ ОБОСНОВАННОСТЬ
каждого candidate.


============================================================
ЦЕЛЕВОЕ ПОЛЕ
============================================================

field_key:
${input.field_key}

Название:
${profileTitle}

Определение задачи:
${profileObjective}


============================================================
СПЕЦИАЛЬНЫЕ ПРАВИЛА ПОЛЯ
============================================================

${
  profileRules.length > 0
    ? profileRules
        .map(
          (rule, index) =>
            `${index + 1}. ${rule}`
        )
        .join('\n')
    : 'Дополнительные field-specific правила не переданы.'
}


============================================================
ОБЩИЕ ПРАВИЛА VALIDATOR
============================================================

1. Не подтверждай candidate только потому,
что его evidence технически существует.

2. Проверяй, действительно ли смысл evidence
подтверждает именно целевое поле
и именно значение candidate.

3. Не путай близкие по смыслу,
но разные сущности.

4. Не извлекай новые facts.

5. Не исправляй значение candidate.

6. Не дополняй candidate сведениями,
которых в нём нет.

7. Не используй внешние знания.

8. Structured tender metadata является
отдельным допустимым источником,
но используй только реально переданные metadata.

9. Наличие одинакового числа,
даты или текста в двух источниках
само по себе не доказывает,
что источники говорят об одном и том же факте.

10. Для отрицательного candidate
вида:

"нет"
"не требуется"
"не предусмотрено"

должно существовать прямое evidence,
подтверждающее именно отрицательный факт.

Простое отсутствие положительного упоминания
не подтверждает отрицательное значение.

11. verdict="confirmed" допустим,
только если логическая связь между candidate
и evidence достаточно надёжна.

12. verdict="requires_review" используй,
если candidate правдоподобен,
но остаётся существенная неоднозначность
или логический разрыв.

13. verdict="rejected" используй,
если evidence не подтверждает candidate,
относится к другому полю
или candidate построен на недопустимом выводе.

14. Каждый входной candidate должен получить
РОВНО ОДНУ validation.

15. Не создавай validations
для несуществующих candidate_index.

16. Возвращай только валидный JSON.


============================================================
ДОПУСТИМЫЕ verdict
============================================================

confirmed
requires_review
rejected


============================================================
ДОПУСТИМЫЕ reason_code
============================================================

insufficient_evidence
ambiguous_scope
unsupported_inference
conflicting_evidence
wrong_field
irrelevant_evidence
other
null


============================================================
ФОРМАТ ОТВЕТА
============================================================

{
  "schema_version": "targeted_recheck_validator_v1",
  "field_key": "${input.field_key}",
  "validations": [
    {
      "candidate_index": 0,
      "verdict": "confirmed",
      "confidence": 0.95,
      "reason_code": null,
      "reason_note": "краткое объяснение"
    }
  ]
}


Если verdict="confirmed":

- reason_code должен быть null;
- reason_note должен объяснить,
  почему evidence действительно подтверждает candidate.


Если verdict="requires_review":

- reason_code не должен быть null;
- reason_note должен объяснить,
  какой существенный вопрос остаётся неразрешённым.


Если verdict="rejected":

- reason_code не должен быть null;
- reason_note должен объяснить,
  почему candidate не следует из evidence.
`.trim();


// ============================================================
// 7. User Prompt
// ============================================================

const userPrompt = `
НЕЗАВИСИМАЯ ПРОВЕРКА TARGETED RECHECK


============================================================
ЦЕЛЕВОЕ ПОЛЕ
============================================================

field_key:
${input.field_key}

Название:
${profileTitle}

Задача:
${profileObjective}


============================================================
ПРИЧИНА TARGETED RECHECK
============================================================

${JSON.stringify(
  input.original_aggregation ?? null,
  null,
  2
)}


============================================================
STRUCTURED TENDER METADATA
============================================================

${JSON.stringify(
  tenderMetadata,
  null,
  2
)}


============================================================
CANDIDATES ПОСЛЕ TARGETED RECHECK
============================================================

${JSON.stringify(
  input.candidates,
  null,
  2
)}


============================================================
ЛОКАЛЬНЫЙ КОНТЕКСТ EVIDENCE
============================================================

${JSON.stringify(
  contextForValidator,
  null,
  2
)}


============================================================
ЗАДАЧА
============================================================

Для каждого переданного candidate:

1. Проверь,
соответствует ли он именно целевому полю.

2. Проверь,
следует ли его значение из evidence.

3. Не извлекай новые сведения.

4. Не исправляй candidate.

5. Верни одну validation
для каждого candidate_index.

Верни результат строго по схеме:

targeted_recheck_validator_v1
`.trim();


// ============================================================
// 8. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    recheck_attempt:
      input.recheck_attempt,

    recheck_outcome:
  input.recheck_outcome,

recheck_note:
  input.recheck_note ?? null,

    candidates:
      input.candidates,

    candidates_count:
      input.candidates.length,

    allowed_candidate_indexes:
      candidateIndexes,

    system_prompt:
      systemPrompt,

    user_prompt:
      userPrompt,

    recheck_profile:
      profile,

    allowed_metadata:
      tenderMetadata,

    original_aggregation:
      input.original_aggregation ?? null,

    existing_candidates:
      Array.isArray(input.existing_candidates)
        ? input.existing_candidates
        : [],

    recheck_context:
      Array.isArray(input.recheck_context)
        ? input.recheck_context
        : [],

    validator_context:
      contextForValidator,

    targeted_recheck_meta:
      input.targeted_recheck_meta ?? null,

    evidence_validated:
      true,
  },
};

