parameters.jsCode:
const aiResponse = $json;

const source =
  $('Подготовить запрос #2 Validator Targeted Recheck').item.json;


// ============================================================
// 1. Проверяем технический ответ AI
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[#2 Validator Targeted Recheck] Нет choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[#2 Validator Targeted Recheck] Некорректный finish_reason=${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[#2 Validator Targeted Recheck] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON
// ============================================================

let result;

try {
  result =
    JSON.parse(content);
}
catch (error) {
  throw new Error(
    `[#2 Validator Targeted Recheck] Невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_VERDICTS =
  new Set([
    'confirmed',
    'requires_review',
    'rejected',
  ]);

const ALLOWED_REASON_CODES =
  new Set([
    'insufficient_evidence',
    'ambiguous_scope',
    'unsupported_inference',
    'conflicting_evidence',
    'wrong_field',
    'irrelevant_evidence',
    'other',
  ]);


// ============================================================
// 4. Проверяем общий контракт
// ============================================================

if (
  result.schema_version !==
  'targeted_recheck_validator_v1'
) {
  throw new Error(
    `[#2 Validator Targeted Recheck] Некорректный schema_version=${result.schema_version}`
  );
}

if (
  result.field_key !==
  source.field_key
) {
  throw new Error(
    `[#2 Validator Targeted Recheck] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}

if (!Array.isArray(result.validations)) {
  throw new Error(
    '[#2 Validator Targeted Recheck] validations должен быть массивом'
  );
}


// ============================================================
// 5. Allow-list candidate_index
// ============================================================

const allowedCandidateIndexes =
  Array.isArray(
    source.allowed_candidate_indexes
  )
    ? source.allowed_candidate_indexes
    : [];

const allowedCandidateIndexSet =
  new Set(
    allowedCandidateIndexes
  );


if (
  result.validations.length !==
  allowedCandidateIndexes.length
) {
  throw new Error(
    `[#2 Validator Targeted Recheck] Ожидалось ${allowedCandidateIndexes.length} validations, получено ${result.validations.length}`
  );
}


// ============================================================
// 6. Проверяем каждую validation
// ============================================================

const usedCandidateIndexes =
  new Set();

const validationMap =
  new Map();


for (const validation of result.validations) {

  // ----------------------------------------------------------
  // candidate_index
  // ----------------------------------------------------------

  if (
    !Number.isInteger(
      validation.candidate_index
    )
  ) {
    throw new Error(
      '[#2 Validator Targeted Recheck] candidate_index должен быть integer'
    );
  }

  if (
    !allowedCandidateIndexSet.has(
      validation.candidate_index
    )
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] Неизвестный candidate_index=${validation.candidate_index}`
    );
  }

  if (
    usedCandidateIndexes.has(
      validation.candidate_index
    )
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] candidate_index повторяется: ${validation.candidate_index}`
    );
  }

  usedCandidateIndexes.add(
    validation.candidate_index
  );


  // ----------------------------------------------------------
  // verdict
  // ----------------------------------------------------------

  if (
    !ALLOWED_VERDICTS.has(
      validation.verdict
    )
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] Недопустимый verdict=${validation.verdict}`
    );
  }


  // ----------------------------------------------------------
  // confidence
  // ----------------------------------------------------------

  if (
    typeof validation.confidence !== 'number' ||
    !Number.isFinite(
      validation.confidence
    ) ||
    validation.confidence < 0 ||
    validation.confidence > 1
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] Некорректный confidence=${validation.confidence}`
    );
  }


  // ----------------------------------------------------------
  // reason_note
  // ----------------------------------------------------------

  if (
    typeof validation.reason_note !== 'string' ||
    !validation.reason_note.trim()
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] Нет reason_note для candidate_index=${validation.candidate_index}`
    );
  }


  // ----------------------------------------------------------
  // confirmed
  // ----------------------------------------------------------

  if (
    validation.verdict ===
    'confirmed'
  ) {

    if (
      validation.reason_code !== null
    ) {
      throw new Error(
        `[#2 Validator Targeted Recheck] Для confirmed reason_code должен быть null`
      );
    }
  }


  // ----------------------------------------------------------
  // requires_review / rejected
  // ----------------------------------------------------------

  if (
    validation.verdict ===
      'requires_review' ||
    validation.verdict ===
      'rejected'
  ) {

    if (
      !ALLOWED_REASON_CODES.has(
        validation.reason_code
      )
    ) {
      throw new Error(
        `[#2 Validator Targeted Recheck] Некорректный reason_code=${validation.reason_code}`
      );
    }
  }


  validationMap.set(
    validation.candidate_index,
    validation
  );
}


// ============================================================
// 7. Проверяем, что никакой candidate не потерян
// ============================================================

for (
  const candidateIndex
  of allowedCandidateIndexes
) {

  if (
    !usedCandidateIndexes.has(
      candidateIndex
    )
  ) {
    throw new Error(
      `[#2 Validator Targeted Recheck] Потерян candidate_index=${candidateIndex}`
    );
  }
}


// ============================================================
// 8. Объединяем candidate + validation
// ============================================================

const sourceCandidates =
  Array.isArray(source.candidates)
    ? source.candidates
    : [];

const validatedCandidates =
  sourceCandidates.map(
    candidate => {

      const validation =
        validationMap.get(
          candidate.candidate_index
        );

      if (!validation) {
        throw new Error(
          `[#2 Validator Targeted Recheck] Нет validation для candidate_index=${candidate.candidate_index}`
        );
      }

      return {
        ...candidate,

        validator_verdict:
          validation.verdict,

        validator_confidence:
          validation.confidence,

        validator_reason_code:
          validation.reason_code,

        validator_reason_note:
          validation.reason_note,
      };
    }
  );


// ============================================================
// 9. Статистика
// ============================================================

const confirmedCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'confirmed'
  ).length;

const requiresReviewCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'requires_review'
  ).length;

const rejectedCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'rejected'
  ).length;


// ============================================================
// 10. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    recheck_attempt:
      source.recheck_attempt,

    recheck_outcome:
      source.recheck_outcome ?? null,

    recheck_note:
      source.recheck_note ?? null,


    candidates:
      validatedCandidates,

    candidates_count:
      validatedCandidates.length,

    confirmed_count:
      confirmedCount,

    requires_review_count:
      requiresReviewCount,

    rejected_count:
      rejectedCount,


    recheck_profile:
      source.recheck_profile ?? null,

    allowed_metadata:
      source.allowed_metadata ?? {},

    original_aggregation:
      source.original_aggregation ?? null,

    existing_candidates:
      Array.isArray(
        source.existing_candidates
      )
        ? source.existing_candidates
        : [],

    recheck_context:
      Array.isArray(
        source.recheck_context
      )
        ? source.recheck_context
        : [],


    targeted_recheck_meta:
      source.targeted_recheck_meta ??
      null,

    validator_meta: {
      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,
    },


    evidence_validated:
      source.evidence_validated === true,

    validator_validated:
      true,
  },
};

const input = $json;


// ============================================================
// 1. Базовые проверки
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Определить путь после Validator] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Определить путь после Validator] Нет field_key'
  );
}

if (input.validator_validated !== true) {
  throw new Error(
