const aiResponse = $json;

const source =
  $('Подготовить запрос #2 AI Targeted Recheck').item.json;


// ============================================================
// 1. Техническая проверка ответа DeepSeek
// ============================================================

class TargetedRecheckValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TargetedRecheckValidationError';
    this.validation_stage =
      /candidate\[[^\]]+\]\.evidence|semantic block|metadata|source_type|analysis_unit_id \+ semantic_block_id|quote/iu
        .test(message)
        ? 'evidence_validation'
        : 'model_response_contract';
  }
}

if (
  !source ||
  typeof source !== 'object' ||
  !source.analysis_run_id ||
  !source.field_key ||
  !Number.isInteger(source.field_index)
) {
  throw new Error(
    '[Targeted Recheck Evidence Validator] Нарушен upstream source invariant'
  );
}

try {

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new TargetedRecheckValidationError(
    '[Targeted Recheck Evidence Validator] Нет choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new TargetedRecheckValidationError(
    `[Targeted Recheck Evidence Validator] Некорректный finish_reason=${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new TargetedRecheckValidationError(
    '[Targeted Recheck Evidence Validator] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON модели
// ============================================================

let result;

try {
  result =
    JSON.parse(content);
} catch (error) {
  throw new TargetedRecheckValidationError(
    `[Targeted Recheck Evidence Validator] Невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_OUTCOMES =
  new Set([
    'candidate_found',
    'insufficient_evidence',
  ]);

const ALLOWED_STATUSES =
  new Set([
    'found',
    'requires_review',
  ]);

const ALLOWED_REVIEW_CODES =
  new Set([
    'insufficient_evidence',
    'ambiguous_scope',
    'conflicting_evidence',
    'template_or_placeholder',
    'other',
  ]);


// ============================================================
// 4. Общий контракт ответа
// ============================================================

if (
  result.schema_version !==
  'targeted_recheck_extractor_v1'
) {
  throw new TargetedRecheckValidationError(
    `[Targeted Recheck Evidence Validator] Некорректный schema_version=${result.schema_version}`
  );
}

if (
  result.field_key !==
  source.field_key
) {
  throw new TargetedRecheckValidationError(
    `[Targeted Recheck Evidence Validator] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}

if (
  !ALLOWED_OUTCOMES.has(
    result.recheck_outcome
  )
) {
  throw new TargetedRecheckValidationError(
    `[Targeted Recheck Evidence Validator] Недопустимый recheck_outcome=${result.recheck_outcome}`
  );
}

if (!Array.isArray(result.candidates)) {
  throw new TargetedRecheckValidationError(
    '[Targeted Recheck Evidence Validator] candidates должен быть массивом'
  );
}


// ============================================================
// 5. Создаём trusted union semantic block evidence
// ============================================================

const allowedBlocks =
  Array.isArray(source.allowed_semantic_blocks)
    ? source.allowed_semantic_blocks
    : [];

const trustedPairMap =
  new Map();


function addTrustedSource({
  analysisUnitId,
  semanticBlockId,
  sourceText,
  origin,
}) {

  if (
    typeof analysisUnitId !== 'string' ||
    !analysisUnitId.trim() ||
    typeof semanticBlockId !== 'string' ||
    !semanticBlockId.trim() ||
    typeof sourceText !== 'string' ||
    !sourceText.trim()
  ) {
    return;
  }


  const normalizedText =
    normalizeEvidenceText(sourceText);

  if (!normalizedText) {
    return;
  }


  const key =
    `${analysisUnitId}\u0000${semanticBlockId}`;

  let trustedPair =
    trustedPairMap.get(key);

  if (!trustedPair) {
    trustedPair = {
      analysis_unit_id:
        analysisUnitId,

      semantic_block_id:
        semanticBlockId,

      sources: [],
    };

    trustedPairMap.set(
      key,
      trustedPair
    );
  }


  const existingSource =
    trustedPair.sources.find(
      sourceEntry =>
        sourceEntry.normalized_text ===
        normalizedText
    );


  if (existingSource) {

    if (
      !existingSource.origins.includes(
        origin
      )
    ) {
      existingSource.origins.push(
        origin
      );
    }

    return;
  }


  trustedPair.sources.push({
    normalized_text:
      normalizedText,

    origins: [
      origin,
    ],
  });
}


for (const block of allowedBlocks) {

  addTrustedSource({
    analysisUnitId:
      block?.analysis_unit_id,

    semanticBlockId:
      block?.semantic_block_id,

    sourceText:
      block?.text,

    origin:
      'targeted_context',
  });
}


const existingCandidates =
  Array.isArray(source.existing_candidates)
    ? source.existing_candidates
    : [];


for (
  const existingCandidate
  of existingCandidates
) {

  const analysisUnitId =
    existingCandidate?.analysis_unit_id;

  if (
    typeof analysisUnitId !== 'string' ||
    !analysisUnitId.trim()
  ) {
    continue;
  }


  const existingEvidence =
    Array.isArray(existingCandidate?.evidence)
      ? existingCandidate.evidence
      : [];


  for (
    const evidence
    of existingEvidence
  ) {

    addTrustedSource({
      analysisUnitId,

      semanticBlockId:
        evidence?.semantic_block_id,

      sourceText:
        evidence?.quote,

      origin:
        'existing_candidate',
    });
  }
}


// ============================================================
// 6. Metadata allow-list
// ============================================================

const allowedMetadata =
  source.allowed_metadata ?? {};


// ============================================================
// 7. Нормализация только пробелов
// ============================================================

function normalizeEvidenceText(value) {
  return String(value ?? '')
    .replace(/\[(?:R\d+(?:-R\d+)?,)?C\d+(?:-C\d+)?\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


// ============================================================
// 8. Проверяем режим insufficient_evidence
// ============================================================

if (
  result.recheck_outcome ===
  'insufficient_evidence'
) {

  if (result.candidates.length !== 0) {
    throw new TargetedRecheckValidationError(
      '[Targeted Recheck Evidence Validator] При insufficient_evidence candidates должен быть пуст'
    );
  }

  if (
    typeof result.recheck_note !== 'string' ||
    !result.recheck_note.trim()
  ) {
    throw new TargetedRecheckValidationError(
      '[Targeted Recheck Evidence Validator] При insufficient_evidence нужен recheck_note'
    );
  }
}


// ============================================================
// 9. Проверяем режим candidate_found
// ============================================================

if (
  result.recheck_outcome ===
  'candidate_found'
) {

  if (result.candidates.length === 0) {
    throw new TargetedRecheckValidationError(
      '[Targeted Recheck Evidence Validator] candidate_found без candidates'
    );
  }
}


// ============================================================
// 10. Проверяем каждого кандидата
// ============================================================

const usedCandidateIndexes =
  new Set();

const verifiedCandidates =
  [];


const evidenceCoordinateRepairs =
  [];


for (
  let candidatePosition = 0;
  candidatePosition < result.candidates.length;
  candidatePosition++
) {

  const candidate =
    result.candidates[candidatePosition];


  // ----------------------------------------------------------
  // candidate_index
  // ----------------------------------------------------------

  if (
    !Number.isInteger(
      candidate.candidate_index
    ) ||
    candidate.candidate_index < 0
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Некорректный candidate_index у кандидата ${candidatePosition}`
    );
  }

  if (
    usedCandidateIndexes.has(
      candidate.candidate_index
    )
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Повтор candidate_index=${candidate.candidate_index}`
    );
  }

  usedCandidateIndexes.add(
    candidate.candidate_index
  );


  // ----------------------------------------------------------
  // value_text
  // ----------------------------------------------------------

  if (
    typeof candidate.value_text !== 'string' ||
    !candidate.value_text.trim()
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Пустой value_text у candidate_index=${candidate.candidate_index}`
    );
  }


  // ----------------------------------------------------------
  // status
  // ----------------------------------------------------------

  if (
    !ALLOWED_STATUSES.has(
      candidate.status
    )
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Недопустимый status=${candidate.status}`
    );
  }


  // ----------------------------------------------------------
  // confidence
  // ----------------------------------------------------------

  if (
    typeof candidate.confidence !== 'number' ||
    !Number.isFinite(candidate.confidence) ||
    candidate.confidence < 0 ||
    candidate.confidence > 1
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Некорректный confidence=${candidate.confidence}`
    );
  }


  // ----------------------------------------------------------
  // found / requires_review
  // ----------------------------------------------------------

  if (candidate.status === 'found') {

    if (
      candidate.review_reason_code !== null
    ) {
      throw new TargetedRecheckValidationError(
        `[Targeted Recheck Evidence Validator] Для found review_reason_code должен быть null`
      );
    }

    if (
      candidate.review_note !== null
    ) {
      throw new TargetedRecheckValidationError(
        `[Targeted Recheck Evidence Validator] Для found review_note должен быть null`
      );
    }
  }


  if (
    candidate.status ===
    'requires_review'
  ) {

    if (
      !ALLOWED_REVIEW_CODES.has(
        candidate.review_reason_code
      )
    ) {
      throw new TargetedRecheckValidationError(
        `[Targeted Recheck Evidence Validator] Некорректный review_reason_code=${candidate.review_reason_code}`
      );
    }

    if (
      typeof candidate.review_note !== 'string' ||
      !candidate.review_note.trim()
    ) {
      throw new TargetedRecheckValidationError(
        '[Targeted Recheck Evidence Validator] Для requires_review нужен review_note'
      );
    }
  }


  // ----------------------------------------------------------
  // evidence
  // ----------------------------------------------------------

  if (
    !Array.isArray(candidate.evidence) ||
    candidate.evidence.length === 0
  ) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] Нет evidence у candidate_index=${candidate.candidate_index}`
    );
  }


  const verifiedEvidence =
    [];


  for (
    let evidenceIndex = 0;
    evidenceIndex < candidate.evidence.length;
    evidenceIndex++
  ) {

    const evidence =
      candidate.evidence[evidenceIndex];

    const evidencePath =
      `candidate[${candidate.candidate_index}].evidence[${evidenceIndex}]`;


    // ========================================================
    // semantic_block evidence
    // ========================================================

    if (
      evidence.source_type ===
      'semantic_block'
    ) {

      if (
        typeof evidence.analysis_unit_id !== 'string' ||
        !evidence.analysis_unit_id
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет analysis_unit_id`
        );
      }

      if (
        typeof evidence.semantic_block_id !== 'string' ||
        !evidence.semantic_block_id
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет semantic_block_id`
        );
      }

      if (
        typeof evidence.quote !== 'string' ||
        !evidence.quote.trim()
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: quote пуст`
        );
      }


      const blockKey =
        `${evidence.analysis_unit_id}\u0000${evidence.semantic_block_id}`;


      const quote =
        normalizeEvidenceText(
          evidence.quote
        );


      if (!quote) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: quote отсутствует в semantic block после нормализации пробелов`
        );
      }


      const reportedPair =
        trustedPairMap.get(
          blockKey
        );


      let effectiveAnalysisUnitId =
        evidence.analysis_unit_id;


      if (reportedPair) {

        const reportedPairMatches =
          reportedPair.sources.some(
            sourceEntry =>
              sourceEntry.normalized_text
                .includes(quote)
          );


        if (!reportedPairMatches) {
          throw new TargetedRecheckValidationError(
            `[Targeted Recheck Evidence Validator] ${evidencePath}: quote отсутствует в semantic block после нормализации пробелов`
          );
        }

      } else {

        const matchingPairs =
          [...trustedPairMap.values()]
            .filter(
              trustedPair =>
                trustedPair.semantic_block_id ===
                  evidence.semantic_block_id &&
                trustedPair.sources.some(
                  sourceEntry =>
                    sourceEntry.normalized_text
                      .includes(quote)
                )
            );


        if (matchingPairs.length === 0) {
          throw new TargetedRecheckValidationError(
            `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестная пара analysis_unit_id + semantic_block_id`
          );
        }


        if (matchingPairs.length > 1) {
          throw new TargetedRecheckValidationError(
            `[Targeted Recheck Evidence Validator] ${evidencePath}: неоднозначная пара analysis_unit_id + semantic_block_id; найдено ${matchingPairs.length} доверенных пар`
          );
        }


        effectiveAnalysisUnitId =
          matchingPairs[0]
            .analysis_unit_id;


        evidenceCoordinateRepairs.push({
          candidate_index:
            candidate.candidate_index,

          evidence_index:
            evidenceIndex,

          reported_analysis_unit_id:
            evidence.analysis_unit_id,

          effective_analysis_unit_id:
            effectiveAnalysisUnitId,

          semantic_block_id:
            evidence.semantic_block_id,

          repair_type:
            'unique_semantic_block_and_exact_normalized_quote',
        });
      }


      verifiedEvidence.push({
        source_type:
          'semantic_block',

        analysis_unit_id:
          effectiveAnalysisUnitId,

        semantic_block_id:
          evidence.semantic_block_id,

        quote:
          evidence.quote,
      });

      continue;
    }


    // ========================================================
    // tender_metadata evidence
    // ========================================================

    if (
      evidence.source_type ===
      'tender_metadata'
    ) {

      if (
        typeof evidence.metadata_key !== 'string' ||
        !evidence.metadata_key
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет metadata_key`
        );
      }


      if (
        !Object.prototype.hasOwnProperty.call(
          allowedMetadata,
          evidence.metadata_key
        )
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестный metadata_key=${evidence.metadata_key}`
        );
      }


      const expectedValue =
        allowedMetadata[
          evidence.metadata_key
        ];

      if (
        JSON.stringify(evidence.value) !==
        JSON.stringify(expectedValue)
      ) {
        throw new TargetedRecheckValidationError(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: metadata value не совпадает. Ожидалось ${JSON.stringify(expectedValue)}, получено ${JSON.stringify(evidence.value)}`
        );
      }


      verifiedEvidence.push({
        source_type:
          'tender_metadata',

        metadata_key:
          evidence.metadata_key,

        value:
          evidence.value,
      });

      continue;
    }


    // ========================================================
    // Неизвестный source_type
    // ========================================================

    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестный source_type=${evidence.source_type}`
    );
  }


  verifiedCandidates.push({
    candidate_index:
      candidate.candidate_index,

    value_text:
      candidate.value_text,

    status:
      candidate.status,

    confidence:
      candidate.confidence,

    evidence:
      verifiedEvidence,

    review_reason_code:
      candidate.review_reason_code,

    review_note:
      candidate.review_note,
  });
}


// ============================================================
// 11. candidate_index должны идти 0..N-1
// ============================================================

const sortedIndexes =
  [...usedCandidateIndexes]
    .sort((a, b) => a - b);

for (
  let index = 0;
  index < sortedIndexes.length;
  index++
) {

  if (sortedIndexes[index] !== index) {
    throw new TargetedRecheckValidationError(
      `[Targeted Recheck Evidence Validator] candidate_index должны идти подряд с 0. Получено: ${sortedIndexes.join(', ')}`
    );
  }
}


// ============================================================
// 12. Возвращаем проверенный ответ
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    recheck_attempt:
      source.recheck_attempt,

    recheck_outcome:
      result.recheck_outcome,

    candidates:
      verifiedCandidates,

    recheck_note:
      result.recheck_note ?? null,

    original_aggregation:
      source.original_aggregation,

    existing_candidates:
      source.existing_candidates,

    recheck_context:
      source.recheck_context,

    recheck_profile:
  source.recheck_profile ?? null,

allowed_metadata:
  source.allowed_metadata ?? {},

    targeted_recheck_meta: {
      evidence_coordinate_repairs:
        evidenceCoordinateRepairs,

      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,
    },

    evidence_validated:
      true,
  },
};

} catch (error) {
  if (!(error instanceof TargetedRecheckValidationError)) {
    throw error;
  }

  const rawContent =
    aiResponse?.choices?.[0]?.message?.content;

  const validationStage =
    error.validation_stage;

  const fallbackMessage =
    `Targeted Recheck завершён безопасным technical requires_review: ${error.message}`;

  return {
    json: {
      analysis_run_id:
        source.analysis_run_id,

      field_catalog_version:
        source.field_catalog_version,

      field_index:
        source.field_index,

      field_key:
        source.field_key,

      recheck_attempt:
        source.recheck_attempt,

      recheck_outcome:
        'technical_failure',

      candidates: [],

      recheck_note:
        fallbackMessage,

      original_aggregation:
        source.original_aggregation,

      existing_candidates:
        Array.isArray(source.existing_candidates)
          ? source.existing_candidates
          : [],

      recheck_context:
        source.recheck_context,

      recheck_profile:
        source.recheck_profile ?? null,

      allowed_metadata:
        source.allowed_metadata ?? {},

      source_field_metadata: {
        analysis_run_id:
          source.analysis_run_id,

        field_catalog_version:
          source.field_catalog_version,

        field_index:
          source.field_index,

        field_key:
          source.field_key,

        recheck_attempt:
          source.recheck_attempt,
      },

      technical_fallback_required:
        true,

      technical_fallback_reason_code:
        'targeted_recheck_model_validation_failed',

      technical_fallback_stage:
        validationStage,

      technical_fallback_error: {
        name:
          error.name,

        message:
          error.message,

        stage:
          validationStage,

        checker_node:
          'Проверить #2 evidence Targeted Recheck',
      },

      targeted_recheck_meta: {
        evidence_coordinate_repairs: [],

        response_id:
          aiResponse?.id ?? null,

        model:
          aiResponse?.model ?? null,

        finish_reason:
          aiResponse?.choices?.[0]?.finish_reason ?? null,

        usage:
          aiResponse?.usage ?? null,

        raw_ai_content:
          typeof rawContent === 'string'
            ? rawContent
            : null,

        raw_ai_response:
          aiResponse,
      },

      evidence_validated:
        false,
    },
  };
}

const input = $json;

// ============================================================
// 1. Базовая проверка
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[requires_review Finalizer] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[requires_review Finalizer] Нет field_key'
  );
}

const original = input.original_aggregation ?? {};

const existingCandidates = Array.isArray(input.existing_candidates)
  ? input.existing_candidates
  : [];

const technicalFallback =
  input.technical_fallback_required === true;

const technicalSourceStatusAllowed =
  original.status === 'requires_recheck' ||
  original.status === 'no_initial_candidates';

if (
  technicalFallback
    ? !technicalSourceStatusAllowed
    : original.status !== 'requires_recheck'
) {
  throw new Error(
    '[requires_review Finalizer] Недопустимый original_aggregation.status для выбранной ветки'
  );
}

// Обычная ветка сохраняет прежний requires_recheck + candidate invariant.
// Technical fallback допускает ровно два проверенных source state и может
// завершиться безопасно без исходного candidate.
if (
  !technicalFallback &&
  existingCandidates.length === 0
) {
  throw new Error(
    '[requires_review Finalizer] Ожидался requires_recheck с существующими candidates'
  );
}

// ============================================================
// Targeted Recheck мог завершиться неудачно двумя способами:
//
// 1. Retrieval вообще не нашёл нового релевантного контекста.
// 2. Контекст нашли, AI проверил его, но evidence недостаточно.
//
// В обоих случаях старый existing candidate нельзя терять:
// поле должно завершиться requires_review.
// ============================================================

const recheckCandidates = Array.isArray(input.candidates)
  ? input.candidates
  : [];

if (
  technicalFallback &&
  (
    input.technical_fallback_reason_code !==
      'targeted_recheck_model_validation_failed' ||
    input.evidence_validated !== false ||
    recheckCandidates.length !== 0 ||
    typeof input.technical_fallback_error?.message !== 'string' ||
    !input.technical_fallback_error.message.trim()
  )
) {
  throw new Error(
    '[requires_review Finalizer] Некорректный technical fallback contract'
  );
}

const noContext =
  input.context_found === false &&
  recheckCandidates.length === 0;

const insufficientAfterAi =
  input.recheck_outcome === 'insufficient_evidence' &&
  recheckCandidates.length === 0;

if (
  !technicalFallback &&
  !noContext &&
  !insufficientAfterAi
) {
  throw new Error(
    '[requires_review Finalizer] Ожидался Targeted Recheck без нового пригодного candidate'
  );
}

// ============================================================
// 2. Выбираем исходный candidate
// ============================================================

// Сначала пытаемся найти candidate,
// который соответствует preliminary_value из Round 1.
let selectedCandidate = existingCandidates.find(candidate =>
  typeof original.preliminary_value === 'string' &&
  typeof candidate?.value_text === 'string' &&
  candidate.value_text.trim() === original.preliminary_value.trim()
);

// Если точного совпадения нет — используем первый исходный candidate.
// Это НЕ делает его resolved: итоговый статус всё равно requires_review.
