// Но сохраняем их для аудита,
// чтобы было понятно:
//
// - что именно предложил Recheck Extractor;
// - почему этот candidate не был принят.
// ============================================================

const rejectedCandidates =
  recheckCandidates
    .filter(
      candidate =>
        candidate.validator_verdict === 'rejected'
    )
    .map(candidate => ({
      candidate_index:
        candidate.candidate_index ?? null,

      value_text:
        candidate.value_text ?? null,

      extractor_status:
        candidate.status ?? null,

      extractor_confidence:
        candidate.confidence ?? null,

      validator_verdict:
        candidate.validator_verdict ?? null,

      validator_confidence:
        candidate.validator_confidence ?? null,

      validator_reason_code:
        candidate.validator_reason_code ?? null,

      validator_reason_note:
        candidate.validator_reason_note ?? null,

      evidence:
        Array.isArray(candidate.evidence)
          ? candidate.evidence
          : [],
    }));


// ============================================================
// 10. Финальный результат
//
// ВАЖНО:
//
// aggregation_status = not_found
//
// НЕ означает:
//
// "нет"
// "не требуется"
// "не предусмотрено"
//
// Это означает:
//
// "после полного анализа предоставленных источников
// значение поля надёжно установить не удалось"
// ============================================================

return {
  json: {

    // --------------------------------------------------------
    // Идентификаторы
    // --------------------------------------------------------

    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,


    // --------------------------------------------------------
    // Финальное состояние поля
    // --------------------------------------------------------

    aggregation_status:
      'not_found',

    final_value_text:
      null,

    confidence:
      null,

    needs_recheck:
      false,

    aggregation_validated:
      true,


    // --------------------------------------------------------
    // Как получили not_found
    // --------------------------------------------------------

    resolution_method:
      resolutionMethod,

    not_found_scope:
      'provided_sources',

    not_found_reason_code:
      notFoundReasonCode,

    not_found_note:
      notFoundNote,


    // --------------------------------------------------------
    // Финального evidence нет
    //
    // Отклонённые evidence ниже сохраняются
    // только как audit trail.
    // --------------------------------------------------------

    evidence:
      [],


    // --------------------------------------------------------
    // Targeted Recheck provenance
    // --------------------------------------------------------

    recheck_attempt:
      input.recheck_attempt ?? null,

    recheck_profile:
      input.recheck_profile ?? null,

    original_aggregation:
      input.original_aggregation ?? null,


    targeted_recheck_result: {

      context_found:
        input.context_found ?? true,

      recheck_outcome:
        input.recheck_outcome ?? null,

      recheck_note:
        input.recheck_note ?? null,

      evidence_validated:
        input.evidence_validated ?? null,

      validator_validated:
        input.validator_validated ?? null,
    },


    // --------------------------------------------------------
    // Validator audit
    // --------------------------------------------------------

    validator_summary:
      validatorSummary,

    rejected_candidates:
      rejectedCandidates,
  },
};

const items = $input.all();

if (items.length === 0) {
  throw new Error(
    '[Подготовить вызов Finalizer] FINAL UPSERT не вернул ни одной строки'
  );
}

const runIds = [
  ...new Set(
    items
      .map(item => item.json.analysis_run_id)
      .filter(Boolean)
  ),
];

if (runIds.length !== 1) {
  throw new Error(
    `[Подготовить вызов Finalizer] Ожидался один analysis_run_id, получено: ${JSON.stringify(runIds)}`
  );
}

const fieldKeys = items
  .map(item => item.json.field_key)
  .filter(Boolean);

return [
  {
    json: {
      analysis_run_id: runIds[0],
      trigger_source: 'targeted_recheck',
      trigger_field_keys: fieldKeys,
    },
  },
];

